                    if (0 <= nr < h and 0 <= nc < w and
                            grid[nr][nc] == color and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        cells.append((nr, nc))
            rows = [rr for rr, _ in cells]
            cols = [cc for _, cc in cells]
            sides = set()
            for rr, cc in cells:
                if rr == 0:
                    sides.add("top")
                if rr == h - 1:
                    sides.add("bottom")
                if cc == 0:
                    sides.add("left")
                if cc == w - 1:
                    sides.add("right")
            objects.append({
                "color": color,
                "cells": cells,
                "sides": sides,
                "box_area": (max(rows) - min(rows) + 1) * (max(cols) - min(cols) + 1),
            })

    boundary_objects = [obj for obj in objects if len(obj["sides"]) >= 2]
    key = max(boundary_objects, key=lambda obj: obj["box_area"])

    def canonical(cells):
        min_r = min(r for r, _ in cells)
        min_c = min(c for _, c in cells)
        points = {(r - min_r, c - min_c) for r, c in cells}
        forms = []
        for turns in range(4):
            rotated = set(points)
            for _ in range(turns):
                rotated = {(c, -r) for r, c in rotated}
            for reflected in (False, True):
                shape = {(r, -c) for r, c in rotated} if reflected else rotated
                top = min(r for r, _ in shape)
                left = min(c for _, c in shape)
                forms.append(frozenset((r - top, c - left) for r, c in shape))
        return min(forms, key=lambda shape: sorted(shape))

    groups = {}
    for obj in objects:
        if obj is not key:
            groups.setdefault(canonical(obj["cells"]), []).append(obj)
    pairs = [group for group in groups.values()
